"""Research ledger after inspecting all 247 ICI questions/options; no app mutations."""
from pathlib import Path
import json,re,math
ROOT=Path(__file__).resolve().parents[1]
s=(ROOT/'ic-study-online/source/study.html').read_text(encoding='utf-8')
bank=json.loads(re.search(r'<script[^>]*id="question-bank"[^>]*>([\s\S]*?)</script>',s)[1]);by={q['id']:q for q in bank}
ex=json.loads(re.search(r'<script id="short-explanations"[^>]*>([\s\S]*?)</script>',s)[1])
refs={
 'dynamic':{'title':'David Harris: Dynamic Circuits, pp. 2–4','url':'https://pages.hmc.edu/harris/class/hal/lect7.pdf'},
 'device':{'title':'David Harris: CMOS transistor and gate fundamentals','url':'https://pages.hmc.edu/harris/class/e158/lect0-intro.pdf'},
 'static':{'title':'David Harris: Static Circuits','url':'https://pages.hmc.edu/harris/class/hal/lect6.pdf'},
 'wire':{'title':'David Harris: Interconnect RC','url':'https://pages.hmc.edu/harris/class/hal/lect4.pdf'},
 'elmore':{'title':'Boyd et al.: Digital Circuit Optimization, RC-tree delay','url':'https://stanford.edu/~boyd/papers/pdf/gp_digital_ckt.pdf'},
 'inverter':{'title':'UBC: CMOS inverter and noise margins','url':'https://courses.ece.ubc.ca/481/lectures/Lecture_06.pdf'},
 'tg':{'title':'UCSB: pass transistors and transmission gates','url':'https://courses.ece.ucsb.edu/ECE125/125_W09Banerjee/Lectures/Lecture4.pdf'},
 'clock':{'title':'Stanford EE371: clocking and domino stages','url':'https://web.stanford.edu/class/archive/ee/ee371/ee371.1066/lectures/Old/Older/lect_10_1up.pdf'}
}
changes=[]
def fix(n,*,question=None,options=None,answer=None,reason=None,tip=None,note,source='device',kind='clarification'):
 q=by[f'ICI211-{n}'];c={}
 if question:c['question']=question
 if options:
  opts=list(q['options'])
  for i,text in options.items():opts[i]=text
  c['options']=opts
 if answer is not None:c['answer']=answer
 changes.append(dict(id=q['id'],changes=c,reason=reason or ex[q['id']]['reason'],tip=tip or ex[q['id']]['tip'],note=note,references=[refs[source]],kind=kind))
fix(259,question='Compared with a single nMOS pass transistor, what signal-transfer benefit does a CMOS transmission gate provide?',options={1:'Passing both strong logic 0 and strong logic 1'},note='Làm rõ full-swing transfer; transmission gate không phải bộ khuếch đại tăng gain.',source='tg')
for n in [261,331]:fix(n,question='What happens to sufficiently small disturbances around an asymptotically stable circuit operating point?',reason='Ổn định tiệm cận nghĩa là nhiễu loạn đủ nhỏ suy giảm và trạng thái trở về điểm cân bằng; ổn định đơn thuần chưa nhất thiết có tính suy giảm.',tip='asymptotically stable → disturbances decay.',note='Thêm điều kiện ổn định tiệm cận để phát biểu suy giảm nhiễu là đúng.')
for n in [264,402]:fix(n,question='In a MOS capacitor with a p-type body, what happens at the semiconductor surface during depletion under a positive gate bias below inversion?',options={1:'Majority holes are repelled from the surface, leaving ionized acceptors'},note='Nêu rõ nền p; chiều loại hạt tải phụ thuộc loại nền.')
for n,index in [(268,3),(490,1)]:fix(n,options={index:'Periodic precharge/evaluate cycles that restore dynamic-node charge'},reason='Nút động lưu điện tích trong pha evaluate; precharge khôi phục điện tích. Không đòi hỏi đường DC liên tục và không nên giữ evaluate vô hạn khi có rò.',tip='dynamic logic → precharge / evaluate, lưu điện tích.',note='Diễn đạt chính xác cơ chế precharge/evaluate thay cho refresh mơ hồ.',source='dynamic')
fix(273,question='While enabled over the signal range, how does the ON resistance of a suitably sized CMOS transmission gate approximately vary?',note='Chỉ xét trạng thái ON; khi OFF, transmission gate không có điện trở thấp.',source='tg')
for n in [293,400,479]:fix(n,question='For a long-channel nMOS in strong inversion, which physical condition marks entry into saturation in the ideal channel model?',reason='Kênh dài vào bão hòa tại VDS ≥ VGS−VT khi pinch-off xuất hiện gần drain. Không áp dụng lời giải này như cơ chế duy nhất cho transistor kênh ngắn.',tip='long-channel saturation → VDS ≥ VGS−VT → pinch-off.',note='Bổ sung mô hình kênh dài để không nhầm với bão hòa vận tốc ở kênh ngắn.')
for n in [295,478]:fix(n,question='Which DC noise-margin property characterizes an ideal CMOS inverter with a VTC symmetric about Vin = Vout = VDD/2?',reason='VTC đối xứng cho các biên nhiễu HIGH và LOW bằng nhau; không đồng nghĩa hai transistor có cùng kích thước hoặc mọi trễ động đều bằng nhau.',tip='symmetric DC VTC → balanced noise margins.',note='Giới hạn ở đặc tính DC; tách khỏi giả thiết trễ lên/xuống bằng nhau.',source='inverter')
fix(306,question='For equal-valued capacitors and a fixed observed output in an RC tree, which capacitor contributes most to the Elmore delay?',reason='Đóng góp của tụ Cj là Cj nhân điện trở chung giữa đường root→tụ và root→output. Chỉ khi Cj bằng nhau mới xếp đóng góp theo điện trở chung.',tip='equal C → largest shared R → largest delay contribution.',note='Thêm điều kiện các tụ bằng nhau và cố định nút quan sát.',source='elmore')
fix(322,question='A flip-flop has setup time 80 ps, clock-to-Q delay 120 ps, and combinational path delay 600 ps. Ignoring clock skew, what is the minimum clock period?',reason='Tmin = tCQ + tcomb + tsetup = 120 + 600 + 80 = 800 ps.',tip='minimum clock period → clock-to-Q + logic + setup.',note='Khôi phục đơn vị ps bị OCR sai; tính lại tổng 800 ps.',source='clock',kind='ocr')
fix(324,question='In conventional domino logic, which element is placed between successive n-type dynamic logic stages to enforce a rising-only evaluation interface?',options={2:'A static inverting CMOS gate, commonly a static inverter'},answer=[2],reason='Ngõ ra tầng động có thể chuyển 1→0 khi evaluate. Đặt cổng đảo tĩnh sau nó tạo tín hiệu 0→1 cho tầng động tiếp theo; đây là cặp dynamic/static của domino.',tip='domino → dynamic gate + static inverter.',note='Đổi khóa D → C; dynamic stage không thay thế cổng đảo tĩnh ngăn giữa các tầng.',source='dynamic',kind='key')
fix(334,question='A wire has R = 2 kΩ and total C = 100 fF. Using the first-order estimate 0.69RC, what delay is expected?',note='Khôi phục kΩ; 0,69×2000×100 fF = 138 ps.',source='wire',kind='ocr')
fix(351,options={0:'Vin near VTN, well below VDD/2'},reason='Với inverter cân đối và ngõ vào quét chậm, dòng trực tiếp lớn nhất xấp xỉ vùng VM≈VDD/2. Gần VTN, NMOS mới bắt đầu dẫn nên dòng chưa cực đại.',tip='peak direct-path current → near VM, not near VTN.',note='Ảnh cũ có A (Vin=Vout) tương đương D tại VM. Chỉnh phương án A để đề một lựa chọn chỉ còn D rõ ràng.',source='inverter',kind='ambiguous_choice')
fix(361,question='For an nMOS whose source-body junction becomes more reverse biased (VSB increases), which device parameter increases?',reason='VT = VT0 + γ[√(2φF+VSB)−√(2φF)]; tăng VSB trong phân cực ngược làm VT tăng.',tip='reverse body bias / VSB↑ → VT↑.',note='Thêm chiều phân cực thân; forward body bias có thể làm VT giảm.')
fix(364,question='In an ideal resistive-load nMOS inverter with its pull-down transistor in cutoff, what is the steady-state DC conduction current, neglecting leakage?',note='Chỉ xét dòng dẫn DC lý tưởng khi transistor kéo xuống cutoff.',source='static')
fix(368,options={0:'Dimensions remain constant while voltage scales by 1/S',1:'Dimensions scale by 1/S while voltage remains constant',3:'Dimensions and voltage both scale by 1/S'},note='Sửa OCR I/S thành 1/S.',kind='ocr')
fix(370,question='In a master-slave transmission-gate flip-flop, which clock-phase arrangement alternately enables the two level-sensitive latches?',options={2:'Complementary, non-overlapping clock phases'},reason='Hai latch được mở ở hai pha khác nhau để tránh cùng trong suốt. Transmission gate tổ hợp nói chung không bắt buộc một sơ đồ clock hai pha.',tip='master/slave TG latches → alternate clock phases.',note='Nêu rõ mạch master-slave; không suy rộng mọi transmission gate đều cần clock hai pha.',source='clock')
fix(372,options={0:'An odd number of at least three inverting stages in a conventional inverter ring'},note='Nêu cấu trúc vòng inverter thông thường có số tầng lẻ ≥3, tránh phương án một inverter mơ hồ.',source='static')
fix(374,question='Under ideal constant-field scaling by S > 1, device dimensions and voltages scale by 1/S. What happens to dynamic power density if clock frequency scales by S?',options={0:'It increases by S³',3:'It decreases by S²'},note='Khôi phục 1/S, S³, S²; phân biệt công suất mỗi cổng với mật độ công suất.',kind='ocr')
fix(378,question='A 30 fF dynamic node initially at 1.2 V shares charge with an initially discharged 10 fF internal node. Ignoring other effects, what is the final voltage?',reason='Bảo toàn điện tích: Vf=(30×1,2+10×0)/(30+10)=0,9 V.',tip='charge sharing → tổng C·V chia tổng C.',note='Khôi phục 10 fF bị OCR thành IO; tính lại chia sẻ điện tích.',source='dynamic',kind='ocr')
fix(384,question='For a symmetric long-channel CMOS inverter with VDD = 1.8 V, VTN = 0.4 V, |VTP| = 0.4 V, and βn = βp, what is the approximate switching threshold VM?',note='Khôi phục VDD, VTN, |VTP| và βn=βp bị mất; VM=0,9 V.',source='inverter',kind='ocr')
fix(398,options={2:'Static Random-Access Memory'},note='Khôi phục đầy đủ chữ Memory trong viết tắt SRAM.',kind='ocr')
fix(407,options={0:'0.16 mW',1:'2.5 mW',2:'16 mW',3:'1.6 mW'},note='Chuẩn hóa đơn vị mW; 0,8 V × 2 mA = 1,6 mW.',kind='ocr')
fix(414,question='In a conventional n-type dynamic gate with an nMOS evaluation transistor driven by CLK, which clock level enables evaluation?',options={3:'CLK = HIGH (active evaluation phase)'},note='Nêu rõ dynamic n-type có transistor evaluate NMOS, tránh đảo cực tính với p-type.',source='dynamic')
fix(423,question='If VDD is reduced from 1.2 V to 0.9 V while α, CL, and f remain unchanged, what fraction of the original dynamic power remains?',options={0:'1.78',2:'1.33',3:'0.75'},reason='Tỷ lệ Pnew/Pold=(0,9/1,2)²=0,5625 khi α, C và f giữ nguyên.',tip='VDD scaling → square of voltage ratio.',note='Khôi phục dấu thập phân và α; giữ đáp án 0,5625.',kind='ocr')
fix(431,question='A manufacturing batch contains 2.0 million fabricated dies, of which 1.5 million pass all tests. What is the manufacturing yield?',note='Sửa chip chứa nhiều dies thành lô sản xuất; yield=75%.',kind='wording')
fix(450,question='A first-order RC node has R = 4 kΩ and C = 50 fF. Using t ≈ 0.69RC, what is the estimated propagation delay?',note='Khôi phục kΩ, fF và dấu xấp xỉ; kết quả 138 ps.',source='wire',kind='ocr')
fix(451,question='A 64 K × 8 memory, with K = 1024 words, stores how many bits in total?',note='Nêu rõ K=1024 và tổ chức theo word; tổng 524288 bits.',kind='clarification')
fix(462,question='Compared with complementary static CMOS implementing the same logic function, what advantage can pseudo-nMOS provide?',note='Bổ sung mốc so sánh để ưu điểm giảm transistor/diện tích có nghĩa.',source='static')
fix(463,question='At a fixed required throughput, how can pipelining potentially reduce dynamic power?',options={1:'Allowing a lower supply voltage by reducing combinational delay per stage'},note='Nêu điều kiện thông lượng cố định; pipeline không tự động giảm công suất nếu không giảm VDD.',source='clock')
fix(474,question='An inverter drives CL = 20 fF through an effective pull-down resistance of 5 kΩ. Using tPHL ≈ 0.69RCL, what is the estimated delay?',note='Sửa kQ và z thành kΩ, ≈; tính lại 69 ps.',source='wire',kind='ocr')
fix(482,question='A two-latch pipeline uses non-overlapping clock phases φ1 and φ2. Why must the phases not overlap?',note='Khôi phục ký hiệu hai pha clock bị OCR hỏng.',source='clock',kind='ocr')
fix(486,question='For a CMOS inverter at a valid steady-state logic level, what is the ideal DC supply current, apart from real-device leakage?',note='Giới hạn ở mức logic hợp lệ; ngõ vào analog giữa hai rail có thể làm cả hai transistor dẫn.',source='static')
change_ids={c['id'] for c in changes}
calculations={301:'NML=.65−.1=.55 V; NMH=1.8−1.05=.75 V; minimum=.55 V.',308:'(W/L)A/(W/L)B=8/2=4.',309:'P doubles with f: 4 mW→8 mW.',322:'120+600+80=800 ps.',329:'log2(1024 words)=10 address bits.',334:'.69×2000×100e−15=138e−12 s.',342:'ID∝W, width ratio 2 implies ID ratio2.',350:'2 fC /20 fF=.10 V.',354:'VDS=.3 < VGS−VT=.8 V and VGS>VT → triode.',369:'sqrt(1048576)=1024 cells/row.',371:'Four equal series resistances require roughly4× each width for unit inverter pull-down.',374:'Cg∝1/S, V²∝1/S², f∝S, density∝S² → constant power/area.',378:'1.2×30/(30+10)=.9 V.',384:'Equal β and |VT| give VM=VDD/2=.9 V.',393:'.2×20e−15×1²×500e6=2e−6 W.',405:'600000/10000=60 USD/functional die.',406:'3 nMOS + 3 pMOS=6 transistors.',407:'.8×.002=.0016 W=1.6 mW.',411:'VDS,sat=VGS−VT=1.8−.5=1.3 V.',422:'PDN conducts for AB+C; series A,B in parallel with C.',423:'(.9/1.2)²=.5625.',431:'1.5/2=.75=75%.',440:'NMH=1.8−1.1=.7; NML=.7−0=.7 V.',444:'256×16=4096 bits.',448:'Tmin=100+750+150=1000 ps → fmax=1 GHz.',450:'.69×4000×50e−15=138 ps.',451:'65536×8=524288 bits.',455:'PDN=(A+B)C, CMOS output is its complement.',465:'Energy drawn from supply CV²=40 fJ; capacitor stores CV²/2=20 fJ.',469:'Mux truth table S0→D0,S1→D1 gives NOT(S)D0+SD1.',474:'.69×5000×20e−15=69 ps.',484:'ID∝Vov², doubling overdrive multiplies current4.'}
ledger=[]
for q in bank:
 if q['subject']!='ICI211':continue
 n=int(q['id'].split('-')[1]);proposal=next((c for c in changes if c['id']==q['id']),None)
 ledger.append(dict(id=q['id'],status='change' if proposal else 'reviewed',selectedAnswer=q['answer'],method='All alternatives inspected; classical circuit model and units checked',rationale=calculations.get(n,(proposal or {}).get('reason',ex[q['id']]['reason']))))
assert len(ledger)==247
out=dict(subject='ICI211',reviewedCount=len(ledger),ledger=ledger,changes=changes,keywordChanges=[],references=list(refs.values()),arithmeticChecks=calculations,notes='One new wrong key (324). Other repairs remove OCR loss or specify assumptions. No claim that a simplified long-channel model applies to every modern device.')
(ROOT/'data/full-audit-ICI211.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'reviewed':len(ledger),'repairs':len(changes),'changedKeys':[c['id'] for c in changes if 'answer' in c['changes']]}))
